export class ConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ConfigError';
  }
}

/**
 * Splits a configuration key path into individual segments, preserving dots within quotes.
 *
 * @param key - The dot- and bracket-delimited configuration key path to split.
 * @returns An array of string segments representing the parsed path.
 * @throws {ConfigError} If the key path contains invalid syntax or unclosed quotes.
 */
export function splitKey(key: string): string[] {
  if (key === '') {
    return [''];
  }

  const parts: string[] = [];
  let current = '';
  let inQuotes = false;
  let quoteChar = '';

  for (let i = 0; i < key.length; i++) {
    const char = key[i];

    if ((char === '"' || char === "'") && (i === 0 || key[i - 1] !== '\\')) {
      if (!inQuotes) {
        inQuotes = true;
        quoteChar = char;
      } else if (char === quoteChar) {
        inQuotes = false;
        quoteChar = '';
      } else {
        current += char;
      }
    } else if (!inQuotes && char === '.') {
      if (current.length > 0) {
        parts.push(current);
        current = '';
      }
    } else if (!inQuotes && char === '[') {
      if (current.length > 0) {
        parts.push(current);
        current = '';
      }
    } else if (!inQuotes && char === ']') {
      if (current.length > 0) {
        parts.push(current);
        current = '';
      }
    } else {
      current += char;
    }
  }

  if (current.length > 0) {
    parts.push(current);
  }
  return parts;
}

function extractReferences(value: any): string[] {
  const refs: string[] = [];
  if (typeof value === 'string') {
    const regex = /\$\{([^}]+)\}/g;
    let match: RegExpExecArray | null;
    while ((match = regex.exec(value)) !== null) {
      refs.push(match[1].trim());
    }
  } else if (Array.isArray(value)) {
    for (const item of value) {
      refs.push(...extractReferences(item));
    }
  } else if (value !== null && typeof value === 'object') {
    for (const val of Object.values(value)) {
      refs.push(...extractReferences(val));
    }
  }
  return refs;
}

function validateCircularReferences(raw: Record<string, any>): void {
  const visitedKeys = new Set<string>();
  const resolvedKeys = new Set<string>();

  function checkCircular(key: string): void {
    if (visitedKeys.has(key)) {
      throw new ConfigError('Circular reference detected');
    }
    if (resolvedKeys.has(key)) {
      return;
    }

    visitedKeys.add(key);

    const value = raw[key];
    const refs = extractReferences(value);
    for (const ref of refs) {
      checkCircular(ref);
    }

    visitedKeys.delete(key);
    resolvedKeys.add(key);
  }

  for (const key of Object.keys(raw)) {
    checkCircular(key);
  }
}

/**
 * Parses a flat record of configuration keys and values into a nested object or array structure.
 *
 * @param raw - The flat configuration record containing dot/bracket notation paths.
 * @returns The structured configuration object with nested objects and arrays.
 * @throws {ConfigError} If a circular reference is detected among configuration values.
 */
export function parseConfig(raw: Record<string, any>): Record<string, any> {
  validateCircularReferences(raw);

  const result: Record<string, any> = {};

  for (const [key, value] of Object.entries(raw)) {
    const parts = splitKey(key);
    let current: any = result;

    for (let i = 0; i < parts.length - 1; i++) {
      const part = parts[i];
      const nextPart = parts[i + 1];
      const isNextIndex = /^\d+$/.test(nextPart);

      if (Array.isArray(current)) {
        const index = parseInt(part, 10);
        if (current[index] === undefined) {
          current[index] = isNextIndex ? [] : {};
        }
        current = current[index];
      } else {
        if (!Object.prototype.hasOwnProperty.call(current, part) || current[part] === undefined) {
          current[part] = isNextIndex ? [] : {};
        }
        current = current[part];
      }
    }

    const lastPart = parts[parts.length - 1];
    const isIndex = /^\d+$/.test(lastPart);
    if (Array.isArray(current) && isIndex) {
      current[parseInt(lastPart, 10)] = value;
    } else {
      current[lastPart] = value;
    }
  }

  return result;
}

