        inQuotes = true;
        quoteChar = char;
      } else if (char === quoteChar) {
        inQuotes = false;
        quoteChar = '';
      } else {
        current += char;
      }
    } else if (!inQuotes && (char === '.' || char === '[' || char === ']')) {
      if (current.length > 0) {
        parts.push(current);
        current = '';
      }
    } else {
      current += char;
    }
  }

  if (current.length > 0) {
    parts.push(current);
  }
  return parts;
}

function extractReferences(value: any): string[] {
  const refs: string[] = [];
  if (typeof value === 'string') {
    const regex = /\$\{([^}]+)\}/g;
    let match: RegExpExecArray | null;
